            var r1 = b.AddInput("resource_input", "Tænd/regulér op", r => r.Note("Kort tryk tænd - langt tryk regulerer lysniveau op\r\n(Udfyldes af installatøren)"));
            var r2 = b.AddInput("resource_input", "Sluk/regulér ned  ", r => r.Note("Kort tryk sluk - langt tryk regulerer lysniveau ned\r\n(Udfyldes af installatøren)"));
            var r3 = b.AddInput("resource_input", "Høj", r => r.Note("Fremkalder højt lysniveau.\r\nTryk over 3 sek. vil gemme det aktuelle lysniveau som høj.\r\nSom kvittering blinker udgang samt diode i frontplade.\r\nNiveau gemmes kun, hvis lysdæmper er tændt.\r\n(Udfyldes af installatøren)"));
            var r4 = b.AddInput("resource_input", "Lav ", r => r.Note("Fremkalder lavt lysniveau.\r\nTryk over 3 sek. vil gemme det aktuelle lysniveau som lav.\r\nSom kvittering blinker udgang samt diode i frontplade.\r\nNiveau gemmes kun, hvis lysdæmper er tændt.\r\n(Udfyldes af installatøren)"));
            var r5 = b.AddInput("resource_input", "Natdrift", r => r.Note("Ved aktivitet (betingelse opfyldt) vil et kort regulerings tryk tænde lyset på \"Lavt niveau\". PIR vil enten være helt eller delvist begrænset.\r\nSammensættes med urfunktion eller dag og nat funktion.\r\n(Udfyldes af installatøren)"));
            var r6 = b.AddInput("resource_input", "PIR", r => r.Note("Forbindes til tilstedeværelses indikering fra PIR sensor.\r\nVirkemåde defineres under indstilling \"# PIR funktion\" og \"# PIR funktion nat\".\r\n(Udfyldes af installatøren)"));
            var r7 = b.AddInput("resource_input", "Skumring", r => r.Note("Forbindes fra skumringssensor eller luxsensor ifm. funktionsblok 1.1.12\r\n(Udfyldes af installatøren)").Inivalue("on"));
            var r8 = b.AddInput("resource_input", "Spærring", r => r.Note("Når denne indgang er on, vil al automatik være spærret. Dette giver mulighed for total spærring i både tændt og slukket tilstand.\r\n(Udfyldes af installatøren)\r\n"));
            var r9 = b.AddOutput("resource_output", "Tænd/regulér op", r => r.Note("Forbindes til klemme 1 på 400 UNI IHC/SA.\r\nSkal forbindes til lysdæmperen for korrekt funktion."));
            var r10 = b.AddOutput("resource_output", "Sluk/regulér ned", r => r.Note("Forbindes til klemme 2 på 400 UNI IHC/SA.\r\nSkal forbindes til lysdæmperen for korrekt funktion."));
            var r11 = b.AddOutput("resource_output", "Lavt niveau - Memory 1", r => r.Note("Forbindes til klemme 3 på UNI Dimmer 400.\r\nSkal forbindes til lysdæmperen for korrekt funktion."));
            var r12 = b.AddOutput("resource_output", "Højt niveau - Memory 2", r => r.Note("Forbindes til klemme 4 på 400 UNI IHC/SA.\r\nSkal forbindes til lysdæmperen for korrekt funktion."));
