            var r15 = b.AddOutput("resource_output", "Manuelt betjent ", r => r.Backup().Note("Visning af overstyring af PIR. \r\nKan benyttes til diode eller Viewer.\r\nIfm. manuel sluk vil udgang blinke (default 15 sek.) som kvittéring for spærring af PIR."));
            var r16 = b.AddOutput("resource_output", "Lysdæmper tændt", r => r.Backup().Note("Status indikering i diode eller Viewer."));
            var r17 = b.AddSetting("resource_enum", "Kort reguleringstryk tænder", r => r.Enum(g1, "Højt niveau").Backup().Note("Her er det muligt, at vælge funktionalitet på reguleringstryk dag/aften.\r\nVælg mellem:\r\n\r\nHøjt niveau\r\nLavt niveau\r\nSidste niveau").Attribute("note-2", "Dette valg er kun aktivt dag/aften. Om natten (natdrift anvendt) vil et kort reguleringstryk tænde lys på lavt niveau.\r\nVed frafald af \"Natdrift\" vil \"Højt niveau\" fremkaldes første gang der trykkes kort reguleringstryk selvom \"Sidste niveau\" er valgt. Dette er valgt fordi ny dag er kommet og gl. niveau ikke er relevant mere. "));
