            var r20 = b.AddSetting("resource_enum", "PIR funktion nat", r => r.Enum(g2, "Trin lav/sluk").Backup().Note("Her er det muligt, at vælge hvilken funktion PIR'en skal have om natten.\r\nNatdrift indgangen skal benyttes for at opnå funktion.\r\n\r\nVælg mellem:\r\n\r\n\"Trin lav/sluk\" kan benyttes til alle rum - dog ikke soverum.\r\n\"Kun efterløb\" benyttes til soverum og andre rum der ønskes undtaget."));
