            cb0.AddAction("%P = OFF", r2, "_0x14", note: "Sætter %P til OFF");
            var cb1 = case0.Case("Case", FbOperand.Enum(g0, "Grøn er \"ON\"", name: "", icon: null), note: "Udfører case når %P er lig case værdien");
