        private static FunctionBlockDefinition FunctionBlock_5_1_02()
        {
            var b = FunctionBlockDefinitionBuilder.Create("5.1.02", "", "Styring af cirkulationspumpe med PIR")
                .VendorMaster()
                .MasterProgrammer("Schneider Electric\r\nCopyrights © 2009")
                .Locked()
                .Attribute("icon", "_0xe")
                .Note("5.1.02. Styring af cirkulationspumpe til varmt brugsvand med PIR\r\n\r\nAnvendelse: \r\nPumpe starter ved aktivering af PIR såfremt der er gået 30 min fra sidste aktivering.\r\n\r\nFor at se den fulde beskrivelse mærker denne linje og tryk \"F1\".\r\nBemærk: Dette virker kun hvis \"Blokken\" er rød-markeret.")
                .CategoryPath("05. Klimastyring\\5.1 Generelt")
                .MasterDate(new DateOnly(2017, 4, 29))
                .InputsNote("Variablene i denne gruppering er input til funktionsblokken")
                .OutputsNote("Variablene i denne gruppering er output fra funktionsblokken")
                .SettingsNote("Variablene i denne gruppering er indstillinger til funktionsblokken")
                .InternalVariablesNote("Variablene i denne gruppe er private variable til funktionsblokken")
                .ProgramsNote("Gruppering af funktionblokkens programmer")
                .Documentation("Cuts heat loss and wasted water at hot-water taps in homes by running the circulation pump only on demand. A PIR motion sensor near a tap triggers a 1-minute pump run (default), but only if the pump has not already run within the last 30 minutes (default). A PIR should be fitted at each hot-water tap; a room light switch can serve as a fallback trigger.")
                .Documentation("Indgang for PIR", "motion sensor signal that triggers the pump")
                .Documentation("Udgang til cirkulationspumpe for varmt vand", "activates the circulation pump");
            var r0 = b.AddInput("resource_input", "Indgang for PIR", r => r.Note("Aktiverer cirkulationspumpe hvis ikke denne har kørt inden for de sidste 30 min.\r\n(Udfyldes af installatøren)"));
            var r1 = b.AddOutput("resource_output", "Udgang til cirkulationspumpe for varmt vand");
            var r2 = b.AddSetting("resource_timer", "Timertid for cirkulation", r => r.Note("Den tid pumpe kører ved aktivering").Attribute("minute", "1"));
            var r3 = b.AddSetting("resource_timer", "Timertid for spærring af pumpestart", r => r.Attribute("minute", "30"));
            var p0 = b.Program("Cirkulationspumpe on").EventsNote("Hændelser").ActionsNote("");
            p0.AddEvent("%P -> ON", r0, "_0xa", note: "Start program når %P antager værdien ON");
            var sub0 = p0.AddSubProgram("Betinget kommando");
            sub0.Conditions.Note("Tilføj betingelser til denne gruppe");
            sub0.Conditions.AddCondition("%P stoppet", r3, "_0xdc", note: "Betingelse at %P ikke tæller op eller ned");
            sub0.WhenTrue.Note("Gruppering af kommandoer som udføres når betingelser er sande");
            sub0.WhenTrue.AddAction("%P = ON", r1, "_0xa", note: "Sætter %P til ON");
            sub0.WhenTrue.AddAction("Sætter %P til Initialværdi og aktiver nedtælling", r2, "_0xbe", note: "Sætter %P til Initialværdi og aktiver nedtælling");
            sub0.WhenTrue.AddAction("Sætter %P til Initialværdi og aktiver nedtælling", r3, "_0xbe", note: "Sætter %P til Initialværdi og aktiver nedtælling");
            sub0.WhenFalse.Note("Gruppering af kommandoer som udføres når betingelser er falske");
            var p1 = b.Program("Cirkulationspumpe off").EventsNote("Hændelser som starter program").ActionsNote("Gruppering af kommandoer som udføres når hændelse er indtruffet");
            p1.AddEvent("%P -> 0", r2, "_0xa", note: "Start program når %P antager tiden 0");
            p1.AddAction("%P = OFF", r1, "_0x14", note: "Sætter %P til OFF");
            return b.Build();
        }

        private static FunctionBlockDefinition FunctionBlock_5_2_01()
        {
            var b = FunctionBlockDefinitionBuilder.Create("5.2.01", "h", "Betjeningspanel")
                .VendorMaster()
                .MasterProgrammer("Schneider Electric\r\nCopyrights © 2009")
                .Locked()
                .Attribute("icon", "_0xe")
                .Note("Panelet anvendes til at vælge drift på klimastyringen af varme og ventilation\r\n\r\nFor at se den fulde beskrivelse mærker denne linje og tryk \"F1\".\r\nBemærk: Dette virker kun hvis \"Blokken\" er rød-markeret.")
                .Attribute("udf", "#5.2.01.a#")
                .CategoryPath("05. Klimastyring\\5.2 Udvidet")
                .MasterDate(new DateOnly(2017, 4, 29))
                .InputsName("Indgang")
                .InputsNote("Variablene i denne gruppering er input til funktionsblokken")
                .OutputsName("Udgang")
                .OutputsNote("Variablene i denne gruppering er output fra funktionsblokken")
                .SettingsNote("Variablene i denne gruppering er indstillinger til funktionsblokken")
                .InternalVariablesNote("Variablene i denne gruppe er private variable til funktionsblokken")
                .ProgramsNote("Gruppering af funktionblokkens programmer")
                .Documentation("This control-panel block lets one button set switch the operating mode (occupied/unoccupied/frost-protection) for all heating circuits at once, driving heating/ventilation blocks such as 5.2.03, 5.2.05, 5.2.06 and 5.3.04. A short press (<1.5s) on a mode input selects that mode; a long press (>1.5s) starts a 30-minute test that forces the actuators open regardless of room temperature, then returns to the previous mode. A separate valve-exercise input cycles valves/pumps periodically to keep them from seizing (for water-based heat only, not electric).")
                .Documentation("Indgang Beboet", "short/long press selects occupied mode / starts test")
                .Documentation("Indgang Frostsikring", "short/long press selects frost-protection mode / starts test")
                .Documentation("Indgang Ubeboet", "short/long press selects unoccupied mode / starts test")
                .Documentation("Indgang for start af ventilmotion", "from FB 5.2.03, exercises valves/pumps while ON")
                .Documentation("Indgang til aktivering og deaktivering af aut. skift til beboet", "enables/disables scheduled auto-switch to occupied")
                .Documentation("Indgang til aktivering og deaktivering af aut. skift til frostsikring", "enables/disables scheduled auto-switch to frost-protection")
                .Documentation("Indgang til aktivering og deaktivering af aut. skift til ubeboet", "enables/disables scheduled auto-switch to unoccupied")
                .Documentation("Udgang automatisk skift til beboet (on ved aktiv)", "auto-switch-to-occupied is armed; disarmed by manual occupied selection")
                .Documentation("Udgang automatisk skift til frostsikring (on ved aktiv)", "auto-switch-to-frost-protection is armed")
                .Documentation("Udgang automatisk skift til ubeboet (on ved aktiv)", "auto-switch-to-unoccupied is armed")
                .Documentation("Udgang beboet (LED ØV)", "lit in occupied mode, blinks during test/valve-exercise")
                .Documentation("Udgang for indikering af test er i gang", "extra test-in-progress indicator")
                .Documentation("Udgang frostsikring (LED NV)", "lit in frost-protection mode, blinks during test/valve-exercise")
                .Documentation("Udgang ubeboet (LED MV)", "lit in unoccupied mode, blinks during test/valve-exercise");
            var g0 = b.AddEnumDefinition("Driftstilstand DK - 3").AddValue("Beboet", 0).AddValue("Ubeboet", 1).AddValue("Frostsikring", 2).AddValue("Gæster", 3).AddValue("Ventilmotion", 5).AddValue("Test", 4);
            var r0 = b.AddInput("resource_input", "Indgang Beboet", r => r.Note("Driftform: \"Beboet\". Ved langt tryk starter testfunktion. Efter test går styringen  tilbage til beboet drift.\r\n(Udfyldes af installatøren)").Attribute("udf", "#I01#"));
            var r1 = b.AddInput("resource_input", "Indgang Ubeboet", r => r.Note("Driftform: \"Ubeboet\". Ved langt tryk starter testfunktion. Efter test går styringen  tilbage til ubeboet drift.\r\n(Udfyldes af installatøren)").Attribute("udf", "#I02#"));
