        private static FunctionBlockDefinition FunctionBlock_5_2_04()
        {
            var b = FunctionBlockDefinitionBuilder.Create("5.2.04", "d", "Ur til nat- og dagtemperatur")
                .VendorMaster()
                .MasterProgrammer("Schneider Electric\r\nCopyrights © 2009")
                .Locked()
                .Attribute("icon", "_0xe")
                .Note("Ur til nat- og dagtemperatur\r\n\r\nBruges til urstyring af nat- og dagtemperatur, med mulighed for overstyring af dagtemperatur. der er ingen dagtemperatur på fridage.\r\nVIGTIGT: Bemærk at urblokken som default kører konstantdrift.\r\n\r\nFor at se den fulde beskrivelse marker denne linje og tryk \"F1\".\r\nBemærk: Dette virker kun hvis \"Blokken\" er rød-markeret.")
                .Attribute("udf", "#5.2.04#")
                .CategoryPath("05. Klimastyring\\5.2 Udvidet")
                .MasterDate(new DateOnly(2017, 4, 29))
                .InputsNote("Variablene i denne gruppering er input til funktionsblokken")
                .OutputsNote("Variablene i denne gruppering er output fra funktionsblokken")
                .SettingsNote("Variablene i denne gruppering er indstillinger til funktionsblokken")
                .InternalVariablesNote("Variablene i denne gruppe er private variable til funktionsblokken")
                .ProgramsName("Ur til nat- og dagtemperatur, med mulighed for overstyring af nat- og dagtemperatur.")
                .ProgramsNote("Gruppering af funktionblokkens programmer")
                .Documentation("Selects between night, day and normal heating temperature, either on a schedule or by manual override; day/night periods only apply once clock operation is enabled, otherwise the block defaults to constant mode with normal temperature. A holiday/day-off input can suppress the day-temperature drop while keeping the usual night switch times.")
                .Documentation("Dag- eller nattemperatur", "on whenever day or night mode is active")
                .Documentation("Dagtemperatur", "on during day temperature; feeds FB 5.2.05 day-temperature input")
                .Documentation("Helligdag eller fridag", "on while the holiday/day-off input is active")
                .Documentation("Konstant", "activates constant (manual) operation, e.g. from app")
                .Documentation("Konstant / urdrift", "toggles between constant and clock operation; defaults to constant at startup")
                .Documentation("Konstant dagtemperatur", "pulse input selecting day temperature in constant mode")
                .Documentation("Konstant nattemperatur", "pulse input selecting night temperature in constant mode")
                .Documentation("Konstant normaltemperatur", "pulse input selecting normal temperature in constant mode")
                .Documentation("Konstantdrift", "on while running in constant mode")
                .Documentation("Nattemperatur", "on during night temperature; feeds FB 5.2.05 night-temperature input")
                .Documentation("Normaltemperatur", "on when normal temperature applies (no day/night active)")
                .Documentation("Urdrift", "on while running in clock (scheduled) mode")
                .Documentation("Urstyret", "activates schedule (clock) operation, e.g. from app");
            var g0 = b.AddEnumDefinition("Natsænkning").AddValue("Natsænkning også ved overstyring", 0).AddValue("Ingen natsænkning ved overstyring", 1);
            var r0 = b.AddInput("resource_input", "Urstyret", r => r.Note("Ved aktivering af urdrift skiftes imellem skift mellem normal-, nat- og dagtemperatur.\r\n(Udfyldes af installatøren)"));
            var r1 = b.AddInput("resource_input", "Konstant", r => r.Note("Konstantdrift anvendes hvis man ikke ønsker urstyret skift mellem normal-, nat- og dagtemperatur.\r\nVed konstantdrift skal man manuelt vælge mellem normal-, nat- og dagtemperatur. \r\nBEMÆRK: Default (ved opstart) er funktionsblokken opsat til at køre i konstantdrift og skifter derved ikke automatisk mellem normal-, dag- eller nattemperatur. Hvis dette ønskes skal man manuelt aktivere urdrift ved at påvirke denne indgang.\r\nTip: Er konstantdrift valgt og man ønsker at anvende nattemperatur kan det tilvælges under indstillinger vælge \"nattemperatur også ved konstantdrift\".\r\n(Udfyldes af installatøren)"));
            var r2 = b.AddInput("resource_input", "Konstant / urdrift", r => r.Note("Ved aktivering skiftes imellem konstant- og urdrift.\r\nKonstantdrift anvendes hvis man ikke ønsker urstyret skift mellem normal-, nat- og dagtemperatur.\r\nVed konstantdrift skal man manuelt vælge mellem normal-, nat- og dagtemperatur. \r\nBEMÆRK: Default (ved opstart) er funktionsblokken opsat til at køre i konstantdrift og skifter derved ikke automatisk mellem normal-, dag- eller nattemperatur. Hvis dette ønskes skal man manuelt aktivere urdrift ved at påvirke denne indgang.\r\nTip: Er konstantdrift valgt og man ønsker at anvende nattemperatur kan det tilvælges under indstillinger vælge \"nattemperatur også ved konstantdrift\".\r\n(Udfyldes af installatøren)").Attribute("udf", "#I01#"));
            var r3 = b.AddInput("resource_input", "Helligdag eller fridag", r => r.Note("Indgang til styring af \"skæve\" fridage og helligdage.\r\nNår indgang er aktiv deaktiveres dagtemperatur således at der er normaltemperatur hele dagen.\r\nManuel overstyring anvendes typisk hvis man er hjemme på en hverdag.\r\nBemærk: Ved denne overstyring vil tidspunkter for skift til nattemperatur på hverdage blive anvendt. \r\n(Udfyldes af installatøren)\r\n\r\n").Attribute("udf", "#I02#"));
            var r4 = b.AddInput("resource_input", "Konstant dagtemperatur", r => r.Note("Pulsindgang til aktivering af konstantdrift dagtemperatur..\r\nKun aktiv hvis konstantdrift er aktiveret.\r\n(Udfyldes af installatøren)"));
            var r5 = b.AddInput("resource_input", "Konstant nattemperatur", r => r.Note("Pulsindgang til aktivering af konstantdrift nattemperatur..\r\nKun aktiv hvis konstantdrift er aktiveret.\r\n(Udfyldes af installatøren)"));
            var r6 = b.AddInput("resource_input", "Konstant normaltemperatur", r => r.Note("Pulsindgang til aktivering af konstantdrift normaltemperatur..\r\nKun aktiv hvis konstantdrift er aktiveret.\r\n(Udfyldes af installatøren)"));
            var r7 = b.AddOutput("resource_output", "Dagtemperatur", r => r.Note("On ved dagtemperatur. Forbindes til FB 5.2.05 - indgang dagtemperatur.\r\nKan også anvendes til indikering.").Attribute("udf", "#O01#"));
