                .Documentation("Indgang Trin 2.", "manual speed step 2 (normal)")
                .Documentation("Indgang Trin 3.", "manual speed step 3 (guest/high-normal)")
                .Documentation("Indgang Trin 4.", "manual speed step 4 (high)")
