            var r2 = b.AddInput("resource_input", "Indgang hygrostat", r => r.Note("Når hygrostat er on, vil anlægget køre i trin 4 ved dag og aften drift. Ved natdrift, vil anlægget køre i trin 2. \r\nDenne indgang kan også anvendes til forceret drift fra f.eks. en timer ifb. toilet besøg.\r\n(Udfyldes af installatøren)\r\n"));
            var r3 = b.AddInput("resource_input", "Indgang gæstetilstand", r => r.Note("Når indgangen er on, sættes ventilationstrin tvungen i trin 3. \r\nDet er ikke muligt at sætte anlægget i gæstetiltand, ved ubeboet og nat.\r\n(Udfyldes af installatøren)"));
            var r4 = b.AddInput("resource_input", "Indgang fri-/ helligdag", r => r.Note("Forbindes sammen med 5.2.04.a. Ur til nat- og dagtemperatur.\r\n\r\nDenne funktion sørger for at huset er ventileret når man kommer hjem.\r\n\r\nEr indgang on, vil indstillingen Drifttrin ikke hjemme på hverdage, før tidspunkt\" ikke være aktiv. \r\n\r\nEr indgang off: Ventilationsanlæget kører indtil indstillingen, \r\nSkift til normal drift på hverdage (ikke hjemme)\r\nNår dette klokkeslet passeres, skiftes til normal drift. \r\n(Udfyldes af installatøren)\r\n"));
