            var r34 = b.AddSetting("resource_enum", "Drift trin gæstetilstand", r => r.Enum(g3, "Trin 3. Normal høj").Backup().Note("Her indstilles ventilationshastigheden for gæstetilstand."));
            var r35 = b.AddSetting("resource_enum", "Drift trin hygrostst on dag", r => r.Enum(g3, "Trin 4. Høj").Backup().Note("Her indstilles ventilationshastigheden når hygrostat er on. Indstillingen gælder kun ved dag.\r\n\r\nNår hygrostat er on, vil anlægget køre i trin 4 ved dag og aften drift. Ved natdrift, vil anlægget køre i trin 2. \r\nDenne indgang kan også anvendes til forceret drift fra f.eks. en timer ifb. toilet besøg.\r\n"));
            var r36 = b.AddSetting("resource_enum", "Drift trin hygrostst on i nattilstand", r => r.Enum(g3, "Trin 2. Normal 1.").Backup().Note("Her indstilles ventilationshastigheden når hygrostat er on.\r\nIndstillingen gælder kun ved nattilstand.\r\n\r\nNår hygrostat er on, vil anlægget køre i trin 4 ved dag og aften drift. Ved natdrift, vil anlægget køre i trin 2. \r\nDenne indgang kan også anvendes til forceret drift fra f.eks. en timer ifb. toilet besøg.\r\n"));
            var r37 = b.AddSetting("resource_enum", "Drift trin hjemme (normal drift)", r => r.Enum(g3, "Trin 1. Svag").Backup().Note("Her indstilles ventilationshastigheden for hjemmetilstand."));
            var r38 = b.AddSetting("resource_enum", "Drifttrin, ude til hverdag, før tidspunkt", r => r.Enum(g3, "Trin 1. Svag").Backup().Note("Drifttrin som er aktivt fra man forlader huset, frem til indstillet tidspunkt for \"Skift til normal drift på hverdag kl.\"\r\n\r\nDenne funktion sørger for at huset er ventileret når man kommer hjem.\r\n\r\n"));
            var r39 = b.AddSetting("resource_enum", "Drifttrin ude til hverdag, efter tidspunkt", r => r.Enum(g3, "Trin 1. Svag").Backup().Note("Drifttrin som er aktivt efter indstillet tidspunkt for \"Skift til normal drift på hverdag kl.\"\r\n\r\nEr Indgang \"fri-/ helligdag indgang on\", vil indstillingen \"Drifttrin ikke hjemme på hverdage, før tidspunkt\" ikke være aktiv. Er indgangen off: Ventilationsanlæget kører \"Drifttrin, ude til hverdag før tidspunkt\" indtil \"Skift til normal drift på hverdage\" (Tidspunkt)\r\n\r\nDenne funktion sørger for at huset er ventileret når man kommer hjem.\r\n"));
            var r40 = b.AddSetting("resource_enum", "Drifttrin ved temp. under setpunkt rørkondens", r => r.Enum(g3, "Trin 1. Svag").Backup().Note("Drifttrin i forhold til \"\r\nTemperatur setpunkt imod frostskader og rørkondens\" \r\nDette sikre at der ikke opstår kondens i stillestående anlæg. Bør ikke sættes til \"slukket\" ved ventilationsrør på loftet.\r\n").Attribute("note-2", "Bør ikke sættes til \"slukket\" ved ventilationsrør på loftet."));
            var r41 = b.AddSetting("resource_enum", "Drifttrin ubeboet", r => r.Enum(g3, "Trin 1. Svag").Backup().Note("Ventilationstrin når betjeningspanel er sat til \"ubeboet\".\r\n Anlægget kører på dette trin 20 min, hver time. (Default)"));
            var r42 = b.AddSetting("resource_timertime", "Drift pr. time i ubeboet", r => r.Backup().Note("Drifttiden som anlæg kører pr. time.\r\n Ved valg af 00:00:00 eller 1 time og derover, vil anlægget kører konstant drift. iht. til valgt trin.\r\n").Attribute("minute", "20"));
            var r43 = b.AddSetting("resource_timertime", "Timertid efterløb når alarm tilsluttes", r => r.Backup().Note("Timertid for efterløb når alarmen tilsluttes.\r\nEfterløbstiden begynder først når hygostaten skifter til off og alarmen er tilskoblet. Dette sikrer at der efterventileres når huset forlades.\r\n").Attribute("minute", "30"));
