        private static FunctionBlockDefinition FunctionBlock_6_3_03()
        {
            var b = FunctionBlockDefinitionBuilder.Create("6.3.03", "a", "Overfaldstryk")
                .VendorMaster()
                .MasterProgrammer("Schneider Electric\r\nCopyrights © 2009")
                .Locked()
                .Attribute("icon", "_0xe")
                .Note("6.3.03.a. Overfaldstryk\r\n\r\nAnvendes til to tast kombinationstryk ifb. med aktivering af overfaldsalarm\r\n\r\nFor at se den fulde beskrivelse marker denne linje og tryk \"F1\".\r\nBemærk: Dette virker kun hvis \"Blokken\" er rød-markeret.")
                .Attribute("helpfile", "6. Alarm\\6.3 Sikkerhed\\6.3.03.pdf")
                .CategoryPath("06. Alarm\\6.3 Sikkerhed")
                .MasterDate(new DateOnly(2017, 4, 29))
                .InputsNote("Variablene i denne gruppering er input til funktionsblokken")
                .OutputsNote("Variablene i denne gruppering er output fra funktionsblokken")
                .SettingsNote("Variablene i denne gruppering er indstillinger til funktionsblokken")
                .InternalVariablesNote("Variablene i denne gruppe er private variable til funktionsblokken")
                .ProgramsNote("Gruppering af funktionblokkens programmer")
                .Documentation("Dual-button panic alarm trigger requiring both buttons pressed together for 2 seconds, guarding against accidental activation; once satisfied it fires a 250 ms pulse to the burglar alarm block's panic input. Not usable with wireless buttons, since a wireless button cannot send two signals simultaneously.")
                .Documentation("Tryk ØH", "right panic button input")
                .Documentation("Tryk ØV", "left panic button input")
                .Documentation("Udgang til alarmblok", "250 ms pulse to alarm block");
            var r0 = b.AddInput("resource_input", "Tryk ØV", r => r.Note("Tryk Venstre og Højre aktiverer overfaldsalarm\r\n(Udfyldes af installatøren)"));
            var r1 = b.AddInput("resource_input", "Tryk ØH", r => r.Note("Tryk Venstre og Højre aktiverer overfaldsalarm\r\n(Udfyldes af installatøren)"));
            var r2 = b.AddOutput("resource_output", "Udgang til alarmblok", r => r.Note("Forbindes til alarmblok, Indgang for overfald"));
            var r3 = b.AddInternalVariable("resource_timer", "ØV/ØH Timer", r => r.Attribute("second", "2"));
            var r4 = b.AddInternalVariable("resource_timer", "PulsTimer", r => r.Attribute("millisecond", "250"));
            var p0 = b.Program("Tryk ØH eller ØV Går on").EventsNote("Hændelser som starter program").ActionsNote("Gruppering af kommandoer som udføres når hændelse er indtruffet");
            p0.AddEvent("%P -> ON", r1, "_0xa", note: "Start program når %P skifter til ON");
            p0.AddEvent("%P -> ON", r0, "_0xa", note: "Start program når %P skifter til ON");
            p0.AddAction("Aktiver nedtælling på %P med initial værdi", r3, "_0xbe", note: "Aktiver nedtælling på %P med initial værdi");
            var p1 = b.Program("ØV/ØH Timer").EventsNote("Hændelser som starter program").ActionsNote("Gruppering af kommandoer som udføres når hændelse er indtruffet");
            p1.AddEvent("%P -> 0", r3, "_0xa", note: "Start program når %P skifter til 0");
            var sub0 = p1.AddSubProgram("ØV skal være on");
            sub0.Conditions.Note("Gruppering af betingelser til logisk test");
            sub0.Conditions.AddCondition("%P = ON", r0, "_0xa", note: "Betingelse at %P er ON");
            sub0.Conditions.AddCondition("%P = ON", r1, "_0xa", note: "Betingelse at %P er ON");
            sub0.WhenTrue.Note("Gruppering af kommandoer som udføres når betingelser er sande");
            sub0.WhenTrue.AddAction("%P = ON", r2, "_0xa", note: "Sætter %P til ON");
            sub0.WhenTrue.AddAction("Aktiver nedtælling på %P med initial værdi", r4, "_0xbe", note: "Aktiver nedtælling på %P med initial værdi");
