        private static FunctionBlockDefinition FunctionBlock_6_3_05()
        {
            var b = FunctionBlockDefinitionBuilder.Create("6.3.05", "", "Røgalarm med logfunktion")
                .VendorMaster()
                .MasterProgrammer("Schneider Electric\r\nCopyrights © 2009")
                .Locked()
                .Attribute("icon", "_0xe")
                .Note("Simpel røgalarm\r\n\r\nFor at se den fulde beskrivelse marker denne linje og tryk \"F1\".\r\nBemærk: Dette virker kun hvis \"Blokken\" er rød-markeret.")
                .Attribute("helpfile", "6. Alarm\\6.3 Sikkerhed\\6.3.01.pdf")
                .CategoryPath("06. Alarm\\6.3 Sikkerhed")
                .MasterDate(new DateOnly(2017, 4, 29))
                .InputsNote("Variablene i denne gruppering er input til funktionsblokken")
                .OutputsNote("Variablene i denne gruppering er output fra funktionsblokken")
                .SettingsNote("Variablene i denne gruppering er indstillinger til funktionsblokken")
                .InternalVariablesNote("Variablene i denne gruppe er private variable til funktionsblokken")
                .ProgramsNote("Gruppering af funktionblokkens programmer")
                .Documentation("Handles smoke detection for a dwelling (use block 6.3.01 instead if gas/water/electricity alarms are also needed). Detection is always active; one input chooses whether only internal sounders react or external sounder and modem/SMS/email notification are also triggered (external on by default). Acknowledging pauses the sensor 15 minutes to avoid retrigger from lingering smoke, doubling as a manual mute (e.g. while cooking); the block also logs the time/date and cause of the last alarm.")
                .Documentation("Ekstern lydgiver", "external sounder, on 15 sec (default).")
                .Documentation("IHC-modem - Røg", "activates the IHC modem.")
                .Documentation("Indgang for ekstern overvågning aktiv", "when ON, routes alarm to external sounder and modem outputs.")
                .Documentation("Indgang for reset af røgindikering", "pulse clears indication, pauses detection 15 min.")
                .Documentation("Indgang for røgsensor", "NC input from the smoke sensor.")
                .Documentation("Indikering af alarm - Røg", "indicates smoke detected; wire to status button.")
                .Documentation("Indikering på lydgiver at alarm genindkobles", "short beep when pause ends, smoke gone.")
                .Documentation("Intern lydgiver", "internal sounder, on 3 min (default).")
                .Documentation("Overstyring af lys", "turns on linked lighting during alarm.")
                .Documentation("Reset af røgsensor", "power-cycles sensor supply to reset it.")
                .Documentation("Udgang for afstilling af modem", "dismisses modem after alarm; used with voice modems.")
                .Documentation("Udgang for indikering af forbikoblet røgalarm", "indicates alarm currently bypassed/paused.");
            var r0 = b.AddInput("resource_input", "Indgang for røgsensor", r => r.Note("Indgang for overvågning af røgudvikling (NC).\r\n(Udfyldes af installatøren)").Inivalue("on"));
            var r1 = b.AddInput("resource_input", "Indgang for reset af røgindikering", r => r.Note("Puls resetter indikering og pauser røgalarm i 15 minuter. Er der stadig røg når pausen er færdig vil der komme røgalarm igen.\r\n(Udfyldes af installatøren)"));
            var r2 = b.AddInput("resource_input", "Indgang for ekstern overvågning aktiv", r => r.Note("Når denne indgang er ON, vil alarmen også blive sendt til udgang for ekstern lydgiver og udgangen for IHC-modem.\r\nKan evt. forbindes til udgang fra tyveriblok således, at alarmen sendes ud af huset når der ikke er nogle hjemme. \r\n(Udfyldes af installatøren)").Inivalue("on"));
            var r3 = b.AddOutput("resource_output", "Overstyring af lys", r => r.Note("Forbindes til indgang for tænd på alle funktionsblokke som ønskes tændt ved røgalarm."));
            var r4 = b.AddOutput("resource_output", "Ekstern lydgiver", r => r.Note("Forbindes til ekstern lydgiver på port 1, ved alarm aktiveres lydgiver i 15 sek (default)."));
            var r5 = b.AddOutput("resource_output", "Intern lydgiver", r => r.Note("Forbindes til intern lydgiver evt. via lydblok. Ved alarm aktiveres lydgiver i 3 minutter (default)"));
            var r6 = b.AddOutput("resource_output", "Indikering på lydgiver at alarm genindkobles", r => r.Note("Efter pausetimer udløber og der ikke er røg tilstede markeres dette med et kort beep. Forbindes til intern lydgiver."));
            var r7 = b.AddOutput("resource_output", "Reset af røgsensor", r => r.Note("Forbindes til forsyning på røgsensor.  Røgsensor resettes ved kort afbrydelse af spænding. Ved anvendelse af flere røgsensore skal man kun konfigurere den ene udgang for forsyning, det er således også kun nødvendigt at linke til den konfiguret udgang. (se evt hjælpefil)").Inivalue("on"));
            var r8 = b.AddOutput("resource_output", "IHC-modem - Røg", r => r.Note("Udgang til at aktivere IHC-Modem"));
            var r9 = b.AddOutput("resource_output", "Indikering af alarm - Røg", r => r.Note("Udgang for indikering af røgalarm detekteret. Forbindes evt. til statustryk."));
